DROP FUNCTION IF EXISTS pg_temp.authz_policy_tests();
CREATE FUNCTION pg_temp.authz_policy_tests() RETURNS TABLE (test text, line text, ok boolean, detail text)
LANGUAGE plpgsql AS $authz_tests$
