    WHEN SQLSTATE 'AZT00' THEN NULL;
    WHEN OTHERS THEN
      PERFORM set_config('role', v_role, true);
      r_test := r_test || (v_test)::text; r_line := r_line || (v_line)::text; r_ok := r_ok || false; r_detail := r_detail || (v_text || E'\n' || 'error: ' || SQLERRM)::text;
  END;
  v_test := 'invariants'; v_line := ''; v_n := 0;
  PERFORM set_config('authz.user_id', '', true), set_config('authz.principal_type', '', true),
          set_config('authz.scopes', '', true);
  FOR v_inv IN SELECT * FROM authz.check_invariants() LOOP
    v_n := v_n + 1;
    r_test := r_test || ('invariant ' || v_inv.invariant)::text; r_line := r_line || ('')::text; r_ok := r_ok || false; r_detail := r_detail || ('invariant ' || v_inv.invariant || ': ' || CASE WHEN starts_with(v_inv.user_id, 'user:') THEN 'user ' || substr(v_inv.user_id, 6) ELSE 'user ' || coalesce(v_inv.user_id, '(nobody)') END || ' can reach ' || v_inv.object_ids::text)::text;
  END LOOP;
  IF v_n = 0 THEN
    r_test := r_test || (v_test)::text; r_line := r_line || ('')::text; r_ok := r_ok || true; r_detail := r_detail || ('1 invariant(s) hold')::text;
  END IF;
  PERFORM set_config('authz.user_id', v_me, true), set_config('authz.principal_type', v_pt, true),
          set_config('authz.scopes', v_scopes, true);
  RETURN QUERY SELECT * FROM unnest(r_test, r_line, r_ok, r_detail);
END $authz_tests$;

DO $t$
DECLARE v record; failures int := 0;
BEGIN
  FOR v IN SELECT * FROM pg_temp.authz_policy_tests() LOOP
    IF v.ok THEN
      RAISE NOTICE 'ok    %', replace(v.detail, E'\n', ' ');
    ELSE
      failures := failures + 1;
      RAISE WARNING 'FAIL  %: %', v.test || CASE WHEN v.line <> '' THEN ' (' || v.line || ')' ELSE '' END, v.detail;
    END IF;
  END LOOP;
  IF failures > 0 THEN RAISE EXCEPTION '% policy test(s) failed', failures; END IF;
END $t$;
DROP FUNCTION pg_temp.authz_policy_tests();
